    ]

    /// Lowercase, no accents or punctuation: "Lékárna Dr.Max" -> "lekarna dr max".
    static func normalize(_ value: String) -> String {
        let folded = value.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "en"))
        let replaced = folded.replacingOccurrences(of: "&", with: " and ")
        let parts = replaced.split(whereSeparator: { !$0.isLetter && !$0.isNumber })
        return parts.joined(separator: " ")
    }

    /// The chain a typed name refers to (exact name or alias).
    static func find(_ name: String) -> Brand? {
        let n = normalize(name)
        guard !n.isEmpty else { return nil }
        return all.first { brand in ([brand.name] + brand.aliases).contains { normalize($0) == n } }
    }

    /// Chains whose name starts with what was typed, best first.
    static func suggest(_ query: String, limit: Int = 6) -> [Brand] {
        let q = normalize(query)
        guard !q.isEmpty else { return [] }
        var starts: [Brand] = []
        var words: [Brand] = []
        for brand in all {
            let names = ([brand.name] + brand.aliases).map(normalize)
            if names.contains(q) { continue }
            if names.contains(where: { $0.hasPrefix(q) }) {
                starts.append(brand)
            } else if names.contains(where: { $0.split(separator: " ").contains { $0.hasPrefix(q) } }) {
                words.append(brand)
            }
        }
        return Array((starts + words).prefix(limit))
    }

    /// Bright colours offered for cards without a known chain.
    static let swatches = [
        "#FF6B6B", "#FF9F43", "#FFC93C", "#2FCB86", "#14B8A6", "#3D9BFF",
        "#3D6BFF", "#7B5CFF", "#C04DE0", "#E0457B", "#C9875A", "#E6E1D6",
    ]
}

extension Card {
    /// Website for the logo: the one saved on the card, else the known chain's.
    var logoDomain: String {
        let own = cleanDomain(website)
        return own.isEmpty ? (Brands.find(name)?.domain ?? "") : own
    }
}

// MARK: - Look.swift

// How a card looks in the wallet: a bright gradient made from its colour, text that
// stays readable on it, and a soft coloured shadow. Black, grey and very dark shop
// colours are swapped for a bright colour of the category, so the wallet never turns black.

struct RGB: Hashable, Sendable {
    var r: Double
    var g: Double
    var b: Double

    init(r: Double, g: Double, b: Double) {
        self.r = r
        self.g = g
        self.b = b
    }

    /// "#RRGGBB" (or "RRGGBB"); nil when it isn't one.
    init?(hex: String) {
        let s = hex.trimmingCharacters(in: .whitespaces).replacingOccurrences(of: "#", with: "")
        guard s.count == 6, let n = UInt32(s, radix: 16) else { return nil }
        r = Double((n >> 16) & 0xFF) / 255
        g = Double((n >> 8) & 0xFF) / 255
        b = Double(n & 0xFF) / 255
    }

    var hex: String {
        let v = [r, g, b].map { Int(($0 * 255).rounded()).clamped(0, 255) }
        return String(format: "#%02X%02X%02X", v[0], v[1], v[2])
    }

    var color: Color { Color(red: r, green: g, blue: b) }

    /// Relative luminance (0 black ... 1 white).
    var luminance: Double {
        func ch(_ c: Double) -> Double { c <= 0.03928 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4) }
        return 0.2126 * ch(r) + 0.7152 * ch(g) + 0.0722 * ch(b)
    }

    /// Hue (degrees), saturation and lightness (0...1).
    var hsl: (h: Double, s: Double, l: Double) {
        let maxV = max(r, g, b)
        let minV = min(r, g, b)
        let l = (maxV + minV) / 2
        guard maxV != minV else { return (0, 0, l) }
        let d = maxV - minV
        let s = l > 0.5 ? d / (2 - maxV - minV) : d / (maxV + minV)
        var h: Double
        if maxV == r {
            h = (g - b) / d + (g < b ? 6 : 0)
        } else if maxV == g {
            h = (b - r) / d + 2
        } else {
            h = (r - g) / d + 4
        }
        h *= 60
        return (h, s, l)
    }

    init(h: Double, s: Double, l: Double) {
        let hue = (h.truncatingRemainder(dividingBy: 360) + 360).truncatingRemainder(dividingBy: 360)
        let sat = min(1, max(0, s))
        let a = sat * min(l, 1 - l)
        func f(_ n: Double) -> Double {
            let k = (n + hue / 30).truncatingRemainder(dividingBy: 12)
            return min(1, max(0, l - a * max(-1, min(k - 3, 9 - k, 1))))
        }
        self.init(r: f(0), g: f(8), b: f(4))
    }

    func mixed(with other: RGB) -> RGB {
        RGB(r: (r + other.r) / 2, g: (g + other.g) / 2, b: (b + other.b) / 2)
    }
}

extension Comparable {
    func clamped(_ low: Self, _ high: Self) -> Self { min(max(self, low), high) }
}

/// The colours of one card.
struct CardLook: Sendable {
    let from: RGB
    let to: RGB
    let lightCard: Bool

    var gradient: LinearGradient {
        LinearGradient(colors: [from.color, to.color], startPoint: .topLeading, endPoint: .bottomTrailing)
    }
    /// Text on the card: white, or warm dark brown on light cards (never black).
    var ink: Color { lightCard ? Theme.darkInk : .white }
    var shadow: Color { to.color.opacity(0.35) }
    /// A single colour for small dots and pins.
    var dot: Color { to.color }
}

enum Looks {
    /// Bright two-stop gradients per category (light end first).
    static let palette: [ShopCategory: (String, String)] = [
        .bakery: ("#FFB347", "#FF6B6B"),
        .grocery: ("#3DD68C", "#0E9F6E"),
        .coffee: ("#E0A16B", "#B5523B"),
        .food: ("#FF9966", "#FF5E62"),
        .pharmacy: ("#4FD1C5", "#0F9B8E"),
        .beauty: ("#FF9AC8", "#E0457B"),
        .fashion: ("#B79CFF", "#7B5CFF"),
        .sport: ("#6FB1FF", "#3D6BFF"),
        .fuel: ("#FFD86B", "#FFA62B"),
        .home: ("#FFC27A", "#FF8A3D"),
        .electronics: ("#5ED0FF", "#2E8CFF"),
        .other: ("#9FA8FF", "#6C63FF"),
    ]
    static let gift = ("#FF9A8B", "#FF5C8A")

    static func look(colorHex: String, category: ShopCategory, kind: CardKind) -> CardLook {
        let base = RGB(hex: colorHex)
        let from: RGB
        let to: RGB
        if let base, base.hsl.l >= 0.2, !(base.hsl.s < 0.15 && base.hsl.l < 0.7) {
            let hsl = base.hsl
            if hsl.l > 0.82 {
                // Pale cards (cream, light blue) stay pale with dark text.
                from = RGB(h: hsl.h, s: hsl.s, l: min(0.95, hsl.l + 0.06))
                to = base
            } else {
                // Lift dark brand colours a little and add a light end for the gradient.
                let l = min(0.58, max(hsl.l, 0.36))
                let s = max(hsl.s, 0.55)
                from = RGB(h: hsl.h - 8, s: s, l: min(0.76, l + 0.15))
                to = RGB(h: hsl.h + 4, s: s, l: l)
            }
        } else {
            // Black, near-black or grey: a bright colour that fits the shop.
            let pair = kind == .gift ? gift : (palette[category] ?? ("#9FA8FF", "#6C63FF"))
            from = RGB(hex: pair.0) ?? RGB(r: 1, g: 0.7, b: 0.3)
            to = RGB(hex: pair.1) ?? RGB(r: 1, g: 0.4, b: 0.4)
        }
        return CardLook(from: from, to: to, lightCard: from.mixed(with: to).luminance > 0.42)
    }
}

extension Card {
    var look: CardLook { Looks.look(colorHex: colorHex, category: category, kind: kind) }
}

/// App colours: warm cream page, deep plum text, one orange-to-coral accent.
enum Theme {
    static let bg = dynamic(light: "#FBF7F1", dark: "#1D1A26")
    static let surface = dynamic(light: "#FFFFFF", dark: "#282434")
    static let surface2 = dynamic(light: "#F5EEE5", dark: "#332E41")
    static let ink = dynamic(light: "#2A2440", dark: "#F4EFFA")
    static let ink2 = dynamic(light: "#5D5672", dark: "#C3BBD3")
    static let ink3 = dynamic(light: "#958EA8", dark: "#8F87A3")
    static let line = dynamic(light: "#EEE5DA", dark: "#3A3449")
    static let accent = Color(red: 1, green: 0.42, blue: 0.37)
    static let warn = Color(red: 0.72, green: 0.38, blue: 0)
    static let darkInk = Color(red: 0.23, green: 0.16, blue: 0.08)
    static var grad: LinearGradient {
        LinearGradient(
            colors: [Color(red: 1, green: 0.70, blue: 0.28), Color(red: 1, green: 0.42, blue: 0.42)],
            startPoint: .topLeading, endPoint: .bottomTrailing
        )
    }

    private static func dynamic(light: String, dark: String) -> Color {
        let l = RGB(hex: light) ?? RGB(r: 1, g: 1, b: 1)
        let d = RGB(hex: dark) ?? RGB(r: 0, g: 0, b: 0)
        return Color(uiColor: UIColor { traits in
            let c = traits.userInterfaceStyle == .dark ? d : l
            return UIColor(red: c.r, green: c.g, blue: c.b, alpha: 1)
        })
    }
}

// MARK: - Barcode.swift

/// Draws card codes. Code 128, QR, PDF417 and Aztec come from Core Image; EAN-13,
/// EAN-8, UPC-A and Code 39 (which Core Image can't make) are encoded here.
@MainActor
enum Barcodes {
    private static let context = CIContext()
    private static var cache: [String: UIImage] = [:]

    // MARK: Guessing and checking

    /// GS1 check digit for the digits given (without the check digit).
    nonisolated static func checkDigit(_ body: String) -> Int {
        var sum = 0
        for (i, ch) in body.reversed().enumerated() {
            let d = ch.wholeNumberValue ?? 0
            sum += i % 2 == 0 ? d * 3 : d
        }
        return (10 - sum % 10) % 10
    }

    nonisolated static func isAsciiDigits(_ s: String) -> Bool {
        !s.isEmpty && s.allSatisfy { $0.isASCII && $0.isNumber }
    }

    nonisolated static func validGS1(_ s: String) -> Bool {
        guard isAsciiDigits(s), s.count >= 8 else { return false }
        return checkDigit(String(s.dropLast())) == s.last?.wholeNumberValue
    }

    /// Best format for a typed number: shop EAN codes when the check digit fits.
    nonisolated static func guess(_ code: String) -> BarcodeFormat {
        let c = code.trimmingCharacters(in: .whitespaces)
        if c.isEmpty { return .none }
        if c.count == 13, validGS1(c) { return .ean13 }
        if c.count == 8, validGS1(c) { return .ean8 }
        if c.count == 12, validGS1(c) { return .upca }
        return .code128
    }

    /// "2 990047 182631" style grouping for reading the number out loud.
    nonisolated static func grouped(_ code: String, _ format: BarcodeFormat) -> String {
        let c = Array(code)
        func part(_ a: Int, _ b: Int) -> String { String(c[a..<b]) }
        switch format {
        case .ean13 where c.count == 13:
            return "\(part(0, 1)) \(part(1, 7)) \(part(7, 13))"
        case .ean8 where c.count == 8:
            return "\(part(0, 4)) \(part(4, 8))"
        case .upca where c.count == 12:
            return "\(part(0, 1)) \(part(1, 6)) \(part(6, 11)) \(part(11, 12))"
        default:
            guard c.count > 8, !code.contains(" ") else { return code }
            return stride(from: 0, to: c.count, by: 4).map { part($0, min($0 + 4, c.count)) }.joined(separator: " ")
        }
    }

    // MARK: Encoders

    private nonisolated static let lCodes = ["0001101", "0011001", "0010011", "0111101", "0100011", "0110001", "0101111", "0111011", "0110111", "0001011"]
    private nonisolated static let gCodes = ["0100111", "0110011", "0011011", "0100001", "0011101", "0111001", "0000101", "0010001", "0001001", "0010111"]
    private nonisolated static let rCodes = ["1110010", "1100110", "1101100", "1000010", "1011100", "1001110", "1010000", "1000100", "1001000", "1110100"]
    private nonisolated static let parity = ["LLLLLL", "LLGLGG", "LLGGLG", "LLGGGL", "LGLLGG", "LGGLLG", "LGGGLL", "LGLGLG", "LGLGGL", "LGGLGL"]

    /// EAN-13 bars (95 modules). Accepts 12 digits (adds the check digit) or 13.
    nonisolated static func ean13(_ code: String) -> [Bool]? {
        guard isAsciiDigits(code), code.count == 12 || code.count == 13 else { return nil }
        let full = code.count == 12 ? code + String(checkDigit(code)) : code
        guard validGS1(full) else { return nil }
        let d = full.compactMap(\.wholeNumberValue)
        var bits = "101"
        let pattern = Array(parity[d[0]])
        for i in 1...6 {
            bits += pattern[i - 1] == "L" ? lCodes[d[i]] : gCodes[d[i]]
        }
        bits += "01010"
        for i in 7...12 {
            bits += rCodes[d[i]]
        }
        bits += "101"
        return bits.map { $0 == "1" }
    }

    /// EAN-8 bars (67 modules). Accepts 7 digits (adds the check digit) or 8.
    nonisolated static func ean8(_ code: String) -> [Bool]? {
        guard isAsciiDigits(code), code.count == 7 || code.count == 8 else { return nil }
        let full = code.count == 7 ? code + String(checkDigit(code)) : code
        guard validGS1(full) else { return nil }
        let d = full.compactMap(\.wholeNumberValue)
        var bits = "101"
        for i in 0..<4 { bits += lCodes[d[i]] }
        bits += "01010"
        for i in 4..<8 { bits += rCodes[d[i]] }
        bits += "101"
        return bits.map { $0 == "1" }
    }

    private nonisolated static let code39Table: [Character: String] = [
        "0": "000110100", "1": "100100001", "2": "001100001", "3": "101100000", "4": "000110001",
        "5": "100110000", "6": "001110000", "7": "000100101", "8": "100100100", "9": "001100100",
        "A": "100001001", "B": "001001001", "C": "101001000", "D": "000011001", "E": "100011000",
        "F": "001011000", "G": "000001101", "H": "100001100", "I": "001001100", "J": "000011100",
        "K": "100000011", "L": "001000011", "M": "101000010", "N": "000010011", "O": "100010010",
        "P": "001010010", "Q": "000000111", "R": "100000110", "S": "001000110", "T": "000010110",
        "U": "110000001", "V": "011000001", "W": "111000000", "X": "010010001", "Y": "110010000",
        "Z": "011010000", "-": "010000101", ".": "110000100", " ": "011000100", "*": "010010100",
        "$": "010101000", "/": "010100010", "+": "010001010", "%": "000101010",
    ]

    /// Code 39 bars: each character is 5 bars and 4 spaces, wide ones three modules.
    nonisolated static func code39(_ code: String) -> [Bool]? {
        let text = "*" + code.uppercased().replacingOccurrences(of: "*", with: "") + "*"
        var out: [Bool] = []
        for ch in text {
            guard let pattern = code39Table[ch] else { return nil }
            for (i, w) in pattern.enumerated() {
                let isBar = i % 2 == 0
                out += Array(repeating: isBar, count: w == "1" ? 3 : 1)
            }
            out.append(false)
        }
        return out
    }

    // MARK: Images

    /// The code as a crisp black-on-white picture (1 point per module; scale with `.interpolation(.none)`).
    static func image(code: String, format: BarcodeFormat) -> UIImage? {
        let trimmed = code.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty, format != .none else { return nil }
        let key = "\(format.rawValue)|\(trimmed)"
        if let hit = cache[key] { return hit }
        let made: UIImage?
        switch format {
        case .ean13:
            made = bars(ean13(trimmed)) ?? coreImage(trimmed, .code128)
        case .upca:
            made = bars(ean13("0" + trimmed)) ?? coreImage(trimmed, .code128)
        case .ean8:
            made = bars(ean8(trimmed)) ?? coreImage(trimmed, .code128)
        case .code39:
            made = bars(code39(trimmed)) ?? coreImage(trimmed, .code128)
        default:
            made = coreImage(trimmed, format)
        }
        if let made {
            cache[key] = made
        }
        return made
    }

    private static func bars(_ modules: [Bool]?) -> UIImage? {
        guard let modules, !modules.isEmpty else { return nil }
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        let size = CGSize(width: modules.count, height: 1)
        return UIGraphicsImageRenderer(size: size, format: format).image { ctx in
            UIColor.white.setFill()
            ctx.fill(CGRect(origin: .zero, size: size))
            UIColor.black.setFill()
            for (x, on) in modules.enumerated() where on {
                ctx.fill(CGRect(x: x, y: 0, width: 1, height: 1))
            }
        }
    }

    private static func coreImage(_ code: String, _ format: BarcodeFormat) -> UIImage? {
        let utf8 = Data(code.utf8)
        let output: CIImage?
        switch format {
        case .qr:
            let f = CIFilter.qrCodeGenerator()
            f.message = utf8
            f.correctionLevel = "M"
            output = f.outputImage
        case .pdf417:
            let f = CIFilter.pdf417BarcodeGenerator()
            f.message = utf8
            output = f.outputImage
        case .aztec:
            let f = CIFilter.aztecCodeGenerator()
            f.message = utf8
            output = f.outputImage
        default:
            guard let ascii = code.data(using: .ascii) else { return nil }
            let f = CIFilter.code128BarcodeGenerator()
            f.message = ascii
            f.quietSpace = 0
            output = f.outputImage
        }
        guard let output, let cg = context.createCGImage(output, from: output.extent) else { return nil }
        return UIImage(cgImage: cg)
    }
}

/// The scannable code, sized for the till: wide for bar codes, square for QR.
struct BarcodeView: View {
    let code: String
    let format: BarcodeFormat
    var height: CGFloat = 110

    var body: some View {
        if let image = Barcodes.image(code: code, format: format) {
            switch format {
            case .qr, .aztec:
                Image(uiImage: image)
                    .interpolation(.none)
                    .resizable()
                    .scaledToFit()
                    .frame(maxWidth: 220, maxHeight: 220)
                    .accessibilityLabel(Text(code))
            case .pdf417:
                Image(uiImage: image)
                    .interpolation(.none)
                    .resizable()
                    .scaledToFit()
                    .frame(maxHeight: height)
                    .accessibilityLabel(Text(code))
            default:
                Image(uiImage: image)
                    .interpolation(.none)
                    .resizable()
                    .frame(maxWidth: .infinity)
                    .frame(height: height)
                    .accessibilityLabel(Text(code))
            }
        } else {
            Text(L("Bez čárového kódu: ukaž číslo.", "No barcode: show the number."))
                .font(.subheadline)
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, minHeight: 60)
        }
    }
}

// MARK: - Store.swift

enum AppTab: Hashable {
    case wallet, coupons, stats, settings
}

struct CardRoute: Hashable {
    let id: UUID
}

struct CouponRoute: Hashable {
    let id: UUID
}

/// Sheets any screen can open.
enum AppSheet: Identifiable {
    case addCard(CardKind)
    case editCard(UUID)
    case addCoupon(UUID?)
    case editCoupon(UUID)
    case promo(UUID)
    case pay(UUID)
    case logSpend(UUID?)

    var id: String {
        switch self {
        case let .addCard(kind): "add-\(kind.rawValue)"
        case let .editCard(id): "edit-\(id)"
        case let .addCoupon(id): "newc-\(id?.uuidString ?? "")"
        case let .editCoupon(id): "ecoupon-\(id)"
        case let .promo(id): "promo-\(id)"
        case let .pay(id): "pay-\(id)"
        case let .logSpend(id): "log-\(id?.uuidString ?? "")"
        }
    }
}

/// A short message at the bottom, optionally with one action (Undo).
struct Toast: Identifiable {
    let id = UUID()
    let text: String
    var actionTitle: String?
    var action: (() -> Void)?
}

/// All of the app's data and actions. Saved as one JSON file on the phone.
@MainActor
@Observable
final class Store {
    static let shared = Store()

    private(set) var data: AppData
    /// Bumps on every change; the app re-syncs shop reminders and notifications on it.
    private(set) var revision = 0

    // Navigation (also used to open a card from a notification).
    var tab: AppTab = .wallet
    var walletPath = NavigationPath()
    var couponsPath = NavigationPath()
    var sheet: AppSheet?
    var bigCode: BigCode?
    var toast: Toast?
    /// Bump to throw confetti.
    var confetti = 0

    // Filled in by LocationService.
    var location: CLLocation?
    var locationStatus: CLAuthorizationStatus = .notDetermined

    @ObservationIgnored private var saveTask: Task<Void, Never>?

    init() {
        data = Store.load() ?? AppData()
    }

    var cards: [Card] { data.cards }
    var coupons: [Coupon] { data.coupons }
    var purchases: [Purchase] { data.purchases }
    var settings: AppSettings { data.settings }

    // MARK: Saving

    private static var fileURL: URL {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return dir.appendingPathComponent("kapsa.json")
    }

    private static func load() -> AppData? {
        guard let raw = try? Data(contentsOf: fileURL) else { return nil }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try? decoder.decode(AppData.self, from: raw)
    }

    private static func encode(_ data: AppData) -> Data? {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        return try? encoder.encode(data)
    }

    private static func write(_ data: AppData) {
        guard let raw = encode(data) else { return }
        let url = fileURL
        try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try? raw.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }

    /// Change the data; saves shortly after (many quick changes become one write).
    func mutate(_ change: (inout AppData) -> Void) {
        change(&data)
        revision += 1
        saveTask?.cancel()
        let snapshot = data
        saveTask = Task {
            try? await Task.sleep(for: .milliseconds(300))
            guard !Task.isCancelled else { return }
            Store.write(snapshot)
        }
    }

    func saveNow() {
        saveTask?.cancel()
        Store.write(data)
    }

    // MARK: Cards

    func card(_ id: UUID) -> Card? {
        data.cards.first { $0.id == id }
    }

    func upsert(_ card: Card) {
        mutate { d in
            if let i = d.cards.firstIndex(where: { $0.id == card.id }) {
                d.cards[i] = card
            } else {
                d.cards.append(card)
            }
        }
    }

    func updateCard(_ id: UUID, _ change: (inout Card) -> Void) {
        mutate { d in
            if let i = d.cards.firstIndex(where: { $0.id == id }) {
                change(&d.cards[i])
            }
        }
    }

    func deleteCard(_ id: UUID) {
        mutate { d in
            let name = d.cards.first { $0.id == id }?.name ?? ""
            d.cards.removeAll { $0.id == id }
            // Coupons and spending stay, with the shop name; they just lose the link.
            for i in d.coupons.indices where d.coupons[i].cardID == id {
                d.coupons[i].cardID = nil
                if d.coupons[i].shop.isEmpty { d.coupons[i].shop = name }
            }
            for i in d.purchases.indices where d.purchases[i].cardID == id {
                d.purchases[i].cardID = nil
            }
        }
    }

    /// Count a card as shown at the till.
    func markUsed(_ id: UUID) {
        updateCard(id) { c in
            c.uses += 1
            c.lastUsedAt = Date()
        }
    }

    /// Add one stamp; true when the reward is now ready.
    @discardableResult
    func addStamp(_ id: UUID) -> Bool {
        var ready = false
        updateCard(id) { c in
            guard var s = c.stamps else { return }
            s.count = min(s.goal, s.count + 1)
            ready = s.isFull
            c.stamps = s
        }
        return ready
    }

    func removeStamp(_ id: UUID) {
        updateCard(id) { c in
            guard var s = c.stamps, s.count > 0 else { return }
            s.count -= 1
            c.stamps = s
        }
    }

    /// Use the reward: start a fresh stamp card.
    func redeemStamps(_ id: UUID) {
        updateCard(id) { c in
            guard var s = c.stamps else { return }
            s.count = 0
            s.redeemed += 1
            c.stamps = s
        }
    }

    func addPlace(_ id: UUID, _ place: Place) {
        updateCard(id) { $0.places.append(place) }
    }

    func removePlace(_ id: UUID, _ placeID: UUID) {
        updateCard(id) { $0.places.removeAll { $0.id == placeID } }
    }

    // MARK: Gift cards

    /// Pay with a gift card: the balance goes down and it counts as spending.
    @discardableResult
    func pay(_ cardID: UUID, amount: Double) -> Purchase? {
        guard let card = self.card(cardID), card.isGift, amount > 0 else { return nil }
        let purchase = Purchase(cardID: cardID, shop: card.name, amount: (amount * 100).rounded() / 100, source: .gift)
        mutate { d in
            if let i = d.cards.firstIndex(where: { $0.id == cardID }) {
                let left = (d.cards[i].balance ?? 0) - amount
                d.cards[i].balance = max(0, (left * 100).rounded() / 100)
            }
            d.purchases.append(purchase)
        }
        return purchase
    }

    /// Take a gift card payment back (the "Undo" after paying).
    func undoPayment(_ purchaseID: UUID) {
        mutate { d in
            guard let p = d.purchases.first(where: { $0.id == purchaseID }) else { return }
            if p.source == .gift, let id = p.cardID, let i = d.cards.firstIndex(where: { $0.id == id }) {
                d.cards[i].balance = ((d.cards[i].balance ?? 0) + p.amount * 100).rounded() / 100
            }
            d.purchases.removeAll { $0.id == purchaseID }
        }
    }

    func setBalance(_ cardID: UUID, _ value: Double) {
        updateCard(cardID) { c in
            c.balance = max(0, value)
            c.initialBalance = max(c.initialBalance ?? 0, value)
        }
    }

    // MARK: Coupons

    func coupon(_ id: UUID) -> Coupon? {
        data.coupons.first { $0.id == id }
    }

    func saveCoupon(_ coupon: Coupon) {
        mutate { d in
            if let i = d.coupons.firstIndex(where: { $0.id == coupon.id }) {
                d.coupons[i] = coupon
            } else {
                d.coupons.append(coupon)
            }
        }
    }

    func deleteCoupon(_ id: UUID) {
        mutate { $0.coupons.removeAll { $0.id == id } }
    }

    /// Mark a coupon used; the saving (if given) counts in the stats.
    func useCoupon(_ id: UUID, saved: Double?) {
        mutate { d in
            if let i = d.coupons.firstIndex(where: { $0.id == id }) {
                d.coupons[i].used = true
                d.coupons[i].usedAt = Date()
                d.coupons[i].saved = saved
            }
        }
    }

    func isActive(_ c: Coupon) -> Bool {
        guard !c.used else { return false }
        guard let e = c.expiry else { return true }
        return e.daysFromToday >= 0
    }

    /// Coupons and promo codes of a card that can still be used, soonest ending first.
    func activeCoupons(for card: Card) -> [Coupon] {
        let name = card.name.lowercased()
        return data.coupons
            .filter { isActive($0) && ($0.cardID == card.id || ($0.cardID == nil && !$0.shop.isEmpty && $0.shop.lowercased() == name)) }
            .sorted { ($0.expiry ?? .distantFuture) < ($1.expiry ?? .distantFuture) }
    }

    func shopName(of coupon: Coupon) -> String {
        if let id = coupon.cardID, let c = card(id) { return c.name }
        return coupon.shop
    }

    // MARK: Spending

    func logPurchase(_ purchase: Purchase) {
        mutate { $0.purchases.append(purchase) }
    }

    func deletePurchase(_ id: UUID) {
        mutate { $0.purchases.removeAll { $0.id == id } }
    }

    func purchases(inMonthOf date: Date) -> [Purchase] {
        let cal = Calendar.current
        return data.purchases
            .filter { cal.isDate($0.date, equalTo: date, toGranularity: .month) }
            .sorted { $0.date > $1.date }
    }

    /// Saved this month: from purchases and from coupons used this month.
    func saved(inMonthOf date: Date) -> Double {
        let cal = Calendar.current
        let fromPurchases = purchases(inMonthOf: date).reduce(0) { $0 + $1.saved }
        let fromCoupons = data.coupons
            .filter { $0.used && $0.usedAt.map { cal.isDate($0, equalTo: date, toGranularity: .month) } == true }
            .reduce(0) { $0 + ($1.saved ?? 0) }
        return fromPurchases + fromCoupons
    }

    // MARK: Settings

    func updateSettings(_ change: (inout AppSettings) -> Void) {
        mutate { change(&$0.settings) }
    }

    // MARK: Where am I

    /// Metres from here to the card's nearest saved place (nil without location or places).
    func distance(to card: Card) -> Double? {
        guard let here = location, !card.places.isEmpty else { return nil }
        return card.places
            .map { CLLocation(latitude: $0.latitude, longitude: $0.longitude).distance(from: here) }
            .min()
    }

    /// The card of the shop you're standing in, if any.
    var hereCard: (card: Card, distance: Double)? {
        let radius = max(settings.radius, 40)
        return data.cards
            .compactMap { c in distance(to: c).map { (card: c, distance: $0) } }
            .filter { $0.distance <= radius }
            .min { $0.distance < $1.distance }
    }

    /// Wallet order: the shop you're in, then nearest, then most used.
    func walletOrder() -> [Card] {
        let here = hereCard?.card.id
        return data.cards.sorted { a, b in
            if a.id == here { return true }
            if b.id == here { return false }
            switch (distance(to: a), distance(to: b)) {
            case let (x?, y?) where abs(x - y) > 50: return x < y
            case (.some, nil): return true
            case (nil, .some): return false
            default: return (a.lastUsedAt ?? a.createdAt) > (b.lastUsedAt ?? b.createdAt)
            }
        }
    }

    // MARK: Opening from notifications

    func open(cardID: UUID) {
        tab = .wallet
        sheet = nil
        var path = NavigationPath()
        if card(cardID) != nil {
            path.append(CardRoute(id: cardID))
        }
        walletPath = path
    }

    func show(_ text: String, actionTitle: String? = nil, action: (() -> Void)? = nil) {
        toast = Toast(text: text, actionTitle: actionTitle, action: action)
    }

    // MARK: Backup

    /// A backup file to share (AirDrop, Files, mail).
    func exportFile() -> URL? {
        guard let raw = Store.encode(data) else { return nil }
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("kapsa-backup.json")
        do {
            try raw.write(to: url, options: .atomic)
            return url
        } catch {
            return nil
        }
    }

    /// Load a backup; items with the same id are replaced, others added. Returns how many.
    func importFile(_ url: URL) -> Int? {
        let access = url.startAccessingSecurityScopedResource()
        defer { if access { url.stopAccessingSecurityScopedResource() } }
        guard let raw = try? Data(contentsOf: url) else { return nil }
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        guard let incoming = try? decoder.decode(AppData.self, from: raw) else { return nil }
        mutate { d in
            for c in incoming.cards {
                d.cards.removeAll { $0.id == c.id }
                d.cards.append(c)
            }
            for c in incoming.coupons {
                d.coupons.removeAll { $0.id == c.id }
                d.coupons.append(c)
            }
            for p in incoming.purchases {
                d.purchases.removeAll { $0.id == p.id }
                d.purchases.append(p)
            }
        }
        return incoming.cards.count + incoming.coupons.count + incoming.purchases.count
    }

    var hasSamples: Bool {
        data.cards.contains { $0.sample } || data.coupons.contains { $0.sample } || data.purchases.contains { $0.sample }
    }

    func removeSamples() {
        mutate { d in
            d.cards.removeAll { $0.sample }
            d.coupons.removeAll { $0.sample }
            d.purchases.removeAll { $0.sample }
        }
    }

    func wipe() {
        walletPath = NavigationPath()
        couponsPath = NavigationPath()
        mutate { $0 = AppData() }
    }
}

// MARK: - Demo.swift

/// Sample cards so the app can be tried before scanning anything real. Everything is
/// marked `sample` and can be removed in Settings.
extension Store {
    func addDemo() {
        let base = location?.coordinate ?? CLLocationCoordinate2D(latitude: 50.08804, longitude: 14.42076)
        func place(_ north: Double, _ east: Double) -> [Place] {
            let lat = base.latitude + north / 111_320
            let lon = base.longitude + east / (111_320 * cos(base.latitude * .pi / 180))
            return [Place(latitude: lat, longitude: lon)]
        }
        func ean(_ body: String) -> String { body + String(Barcodes.checkDigit(body)) }
        let day: TimeInterval = 86_400
        let now = Date()

        let bb = Card(
            name: "Bageterie Boulevard", code: ean("299004718263"), format: .ean13, colorHex: "#1E1E1E",
            category: .bakery, places: place(6, -4),
            stamps: Stamps(goal: 8, count: 5, reward: L("Bageta zdarma", "Free baguette"), redeemed: 1),
            uses: 5, sample: true
        )
        let albert = Card(
            name: "Albert", code: ean("859400127734"), format: .ean13, colorHex: "#003C8F",
            category: .grocery, places: place(240, 180), points: 380, pointsGoal: 500, sample: true
        )
        let dm = Card(
            name: "dm", code: "PB-3089-4410-7752", format: .qr, colorHex: "#FFD23F",
            category: .beauty, places: place(-620, 410), points: 1240, expiry: now.addingTimeInterval(12 * day), sample: true
        )
        let costa = Card(
            name: "Costa Coffee", code: "6061012345678901", format: .code128, colorHex: "#6D1F37",
            category: .coffee, places: place(900, -1200),
            stamps: Stamps(goal: 10, count: 9, reward: L("Káva zdarma", "Free coffee")), sample: true
        )
        let ikea = Card(
            name: "IKEA", code: "6033004512348812", format: .code128, colorHex: "#0058A3",
            category: .home, kind: .gift, places: place(-1400, 900), expiry: now.addingTimeInterval(120 * day),
            balance: 1500, initialBalance: 2000, pin: "4821", sample: true
        )
        let coupons = [
            Coupon(title: L("Celý nákup", "Whole shop"), discount: "−20 %", cardID: dm.id, code: "DM20NOV", format: .qr,
                   expiry: now.addingTimeInterval(2 * day), note: L("Nad 300 Kč", "Over 300 CZK"), sample: true),
            Coupon(title: L("Promo kód", "Promo code"), discount: "−15 %", cardID: albert.id, code: "ALBERT15", format: .code128,
                   expiry: now.addingTimeInterval(20 * day), sample: true),
            Coupon(title: L("Druhá bageta", "Second baguette"), discount: "1+1", cardID: bb.id, sample: true),
        ]
        var purchases: [Purchase] = [
            Purchase(cardID: ikea.id, shop: "IKEA", amount: 500, date: now.addingTimeInterval(-20 * day), source: .gift, sample: true),
        ]
        // Six months of spending, so the stats screen has something to show.
        let cal = Calendar.current
        let spend: [(Card, [Double])] = [(albert, [412, 238, 690, 155]), (bb, [139, 129, 149]), (dm, [324, 189]), (costa, [89, 95])]
        for m in 0..<6 {
            guard let month = cal.date(byAdding: .month, value: -m, to: now) else { continue }
            for (card, amounts) in spend {
                for (i, amount) in amounts.enumerated() {
                    var parts = cal.dateComponents([.year, .month], from: month)
                    parts.day = min(27, 2 + i * 6 + (m * 3) % 5)
                    parts.hour = 12
                    guard let date = cal.date(from: parts), date <= now else { continue }
                    let factor = 0.8 + Double((m + i) % 4) * 0.12
                    purchases.append(Purchase(cardID: card.id, shop: card.name, amount: (amount * factor).rounded(),
                                              saved: i == 0 ? 15 : 0, date: date, sample: true))
                }
            }
        }
        mutate { d in
            d.cards += [bb, albert, dm, costa, ikea]
            d.coupons += coupons
            d.purchases += purchases
        }
    }
}

// MARK: - Notifier.swift

/// Phone notifications: "you've been in the shop 2 minutes, show your card" and
/// reminders before coupons, cards and gift cards expire.
@MainActor
enum Notifier {
    private static let dwellKey = "kapsa.dwellScheduledAt"
    /// Don't remind about the same card again within this time.
    private static let repeatAfter: TimeInterval = 3 * 3600

    static func requestPermission() async -> Bool {
        (try? await UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge])) ?? false
    }

    static func isAllowed() async -> Bool {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        return settings.authorizationStatus == .authorized || settings.authorizationStatus == .provisional
    }

    // MARK: In the shop for a few minutes

    /// Walked into a shop with a card: remind to use it after `minutes`, unless the person
    /// leaves first (`leftShop` cancels it). Once per visit, at most every 3 hours.
    static func enteredShop(cardID: UUID, title: String, body: String, minutes: Int) async {
        let id = "dwell-\(cardID.uuidString)"
        let center = UNUserNotificationCenter.current()
        let pending = await center.pendingNotificationRequests()
        if pending.contains(where: { $0.identifier == id }) {
            return
        }
        var log = UserDefaults.standard.dictionary(forKey: dwellKey) as? [String: Double] ?? [:]
        if let last = log[cardID.uuidString], Date().timeIntervalSince1970 - last < repeatAfter {
            return
        }
        let content = UNMutableNotificationContent()
        content.title = title
        content.body = body
        content.sound = .default
        content.userInfo = ["card": cardID.uuidString]
        let delay = TimeInterval(max(1, minutes) * 60)
        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: delay, repeats: false)
        do {
            try await center.add(UNNotificationRequest(identifier: id, content: content, trigger: trigger))
            log[cardID.uuidString] = Date().timeIntervalSince1970 + delay
            UserDefaults.standard.set(log, forKey: dwellKey)
        } catch {
            // Not allowed: the in-app reminder still works while Kapsa is open.
        }
    }

    /// Left the shop before the reminder fired: cancel it and allow the next visit.
    static func leftShop(cardID: UUID) {
        let id = "dwell-\(cardID.uuidString)"
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: [id])
        var log = UserDefaults.standard.dictionary(forKey: dwellKey) as? [String: Double] ?? [:]
        if let due = log[cardID.uuidString], due > Date().timeIntervalSince1970 {
            log[cardID.uuidString] = nil
            UserDefaults.standard.set(log, forKey: dwellKey)
        }
    }

    // MARK: Expiry reminders

    /// One reminder to schedule: when, what, and which card or coupon it opens.
    struct Reminder: Sendable {
        let id: String
        let date: Date
        let title: String
        let body: String
        let cardID: UUID?
    }

    /// Replace all expiry reminders (at 9:00, a few days before).
    static func scheduleExpiry(_ reminders: [Reminder]) async {
        let center = UNUserNotificationCenter.current()
        let pending = await center.pendingNotificationRequests()
        let old = pending.map(\.identifier).filter { $0.hasPrefix("exp-") }
        center.removePendingNotificationRequests(withIdentifiers: old)
        // iOS keeps at most 64 pending notifications; leave room for the shop reminders.
        let upcoming = reminders.filter { $0.date > Date() }.sorted { $0.date < $1.date }.prefix(48)
        for r in upcoming {
            let content = UNMutableNotificationContent()
            content.title = r.title
            content.body = r.body
            content.sound = .default
            if let cardID = r.cardID {
                content.userInfo = ["card": cardID.uuidString]
            }
            let parts = Calendar.current.dateComponents([.year, .month, .day, .hour, .minute], from: r.date)
            let trigger = UNCalendarNotificationTrigger(dateMatching: parts, repeats: false)
            try? await center.add(UNNotificationRequest(identifier: "exp-\(r.id)", content: content, trigger: trigger))
        }
    }

    /// What to remind about, from the current data. Pure, so it is easy to reason about.
    static func expiryReminders(cards: [Card], coupons: [Coupon], settings: AppSettings) -> [Reminder] {
        guard settings.expiryReminders else { return [] }
        let cal = Calendar.current
        func at9(_ day: Date, before days: Int) -> Date? {
            guard let d = cal.date(byAdding: .day, value: -days, to: cal.startOfDay(for: day)) else { return nil }
            return cal.date(bySettingHour: 9, minute: 0, second: 0, of: d)
        }
        var out: [Reminder] = []
        for c in coupons where !c.used {
            guard let e = c.expiry, let when = at9(e, before: settings.remindDays) else { continue }
            let what = [c.discount, c.title].filter { !$0.isEmpty }.joined(separator: " · ")
            out.append(Reminder(id: "c-\(c.id.uuidString)", date: when, title: L("Kupón brzy končí", "Coupon ending soon"), body: what, cardID: c.cardID))
        }
        for card in cards {
            guard let e = card.expiry else { continue }
            if card.isGift {
                let left = card.balance ?? 0
                guard left > 0, let when = at9(e, before: 14) else { continue }
                out.append(Reminder(
                    id: "g-\(card.id.uuidString)", date: when,
                    title: L("Dárková karta brzy vyprší", "Gift card expiring soon"),
                    body: L("\(card.name) · zbývá \(money(left, settings.currency))", "\(card.name) · \(money(left, settings.currency)) left"),
                    cardID: card.id
                ))
            } else if let when = at9(e, before: max(settings.remindDays, 7)) {
                out.append(Reminder(id: "k-\(card.id.uuidString)", date: when, title: L("Karta brzy končí", "Card expiring soon"), body: card.name, cardID: card.id))
            }
        }
        return out
    }
}

// MARK: - Location.swift

/// Where the phone is, and the shop reminders that work even when Kapsa is closed:
/// iOS watches up to 20 saved shop places ("regions") and wakes the app when you walk
/// in or out. Walking in starts the "show your card" reminder; walking out cancels it.
@MainActor
final class LocationService: NSObject, CLLocationManagerDelegate {
    static let shared = LocationService()

    private let manager = CLLocationManager()
    private var lastSyncLocation: CLLocation?
    private var hereCardID: UUID?

    override init() {
        super.init()
        manager.delegate = self
        manager.desiredAccuracy = kCLLocationAccuracyNearestTenMeters
        manager.distanceFilter = 10
        Store.shared.locationStatus = manager.authorizationStatus
    }

    var canUseLocation: Bool {
        let s = manager.authorizationStatus
        return s == .authorizedWhenInUse || s == .authorizedAlways
    }

    func requestWhenInUse() {
        manager.requestWhenInUseAuthorization()
    }

    /// Needed for shop reminders while the app is closed.
    func requestAlways() {
        manager.requestAlwaysAuthorization()
    }

    /// Live updates while the app is on screen.
    func startUpdating() {
        if canUseLocation {
            manager.startUpdatingLocation()
        }
    }

    func stopUpdating() {
        manager.stopUpdatingLocation()
    }

    // MARK: Shop regions

    /// Watch the saved places nearest to you (iOS allows 20 at a time).
    func syncRegions() {
        let store = Store.shared
        for region in manager.monitoredRegions where region.identifier.hasPrefix("kapsa|") {
            manager.stopMonitoring(for: region)
        }
        guard manager.authorizationStatus == .authorizedAlways,
              store.settings.dwellOn,
              CLLocationManager.isMonitoringAvailable(for: CLCircularRegion.self)
        else { return }
        let here = store.location
        var spots: [(id: String, center: CLLocationCoordinate2D, distance: Double)] = []
        for card in store.cards {
            for place in card.places {
                let center = CLLocationCoordinate2D(latitude: place.latitude, longitude: place.longitude)
                let d = here?.distance(from: CLLocation(latitude: place.latitude, longitude: place.longitude)) ?? 0
                spots.append((id: "kapsa|\(card.id.uuidString)|\(place.id.uuidString)", center: center, distance: d))
            }
        }
        spots.sort { $0.distance < $1.distance }
        // iOS needs about 100 m to notice entering a region reliably.
        let radius = min(max(store.settings.radius, 100), manager.maximumRegionMonitoringDistance)
        for spot in spots.prefix(20) {
            let region = CLCircularRegion(center: spot.center, radius: radius, identifier: spot.id)
            region.notifyOnEntry = true
            region.notifyOnExit = true
            manager.startMonitoring(for: region)
        }
        lastSyncLocation = here
    }

    // MARK: Here (app open)

    /// Called after every location change: the in-app "you're here" and its reminder.
    private func updateHere() {
        let store = Store.shared
        let now = store.hereCard?.card.id
        if now != hereCardID {
            if let old = hereCardID {
                Notifier.leftShop(cardID: old)
            }
            hereCardID = now
            if let now {
                UINotificationFeedbackGenerator().notificationOccurred(.success)
                enteredShop(cardID: now)
            }
        }
        // Moved far: watch the places around the new spot instead.
        if let loc = store.location, lastSyncLocation.map({ $0.distance(from: loc) > 2000 }) ?? true {
            syncRegions()
        }
    }

    /// Start the "show your card" reminder for a card's shop.
    func enteredShop(cardID: UUID) {
        let store = Store.shared
        guard store.settings.dwellOn, let card = store.card(cardID) else { return }
        let coupons = store.activeCoupons(for: card).count
        var extras: [String] = []
        if card.isGift {
            extras.append(L("Zbývá \(money(card.balance ?? 0, store.settings.currency))", "\(money(card.balance ?? 0, store.settings.currency)) left"))
        }
        if coupons > 0 {
            extras.append(L("\(coupons) kupón(y)", "\(coupons) coupon(s)"))
        }
        if let s = card.stamps {
            extras.append(L("razítka \(s.count)/\(s.goal)", "stamps \(s.count)/\(s.goal)"))
        }
        let title = L("Jsi v \(card.name): ukaž kartu", "At \(card.name): show your card")
        let body = ([L("Ať ti nic neuteče.", "Don't miss out.")] + extras).joined(separator: " ")
        let minutes = store.settings.dwellMinutes
        Task {
            await Notifier.enteredShop(cardID: cardID, title: title, body: body, minutes: minutes)
        }
    }

    // MARK: CLLocationManagerDelegate (iOS calls these off the main actor)

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        let status = manager.authorizationStatus
        Task { @MainActor in
            Store.shared.locationStatus = status
            if status == .authorizedWhenInUse || status == .authorizedAlways {
                self.startUpdating()
            }
            self.syncRegions()
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard let last = locations.last, last.horizontalAccuracy >= 0, last.horizontalAccuracy < 500 else { return }
        let lat = last.coordinate.latitude
        let lon = last.coordinate.longitude
        let accuracy = last.horizontalAccuracy
        Task { @MainActor in
            let next = CLLocation(
                coordinate: CLLocationCoordinate2D(latitude: lat, longitude: lon),
                altitude: 0, horizontalAccuracy: accuracy, verticalAccuracy: -1, timestamp: Date()
            )
            let store = Store.shared
            // Ignore tiny GPS wobble so the screen doesn't jump.
            if let old = store.location, old.distance(from: next) < 8, abs(old.horizontalAccuracy - accuracy) < 15 {
                return
            }
            store.location = next
            self.updateHere()
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        // Temporary GPS trouble: keep the last known position.
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didEnterRegion region: CLRegion) {
        let id = region.identifier
        Task { @MainActor in
            if let cardID = LocationService.cardID(from: id) {
                self.enteredShop(cardID: cardID)
            }
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didExitRegion region: CLRegion) {
        let id = region.identifier
        Task { @MainActor in
            if let cardID = LocationService.cardID(from: id), cardID != self.hereCardID {
                Notifier.leftShop(cardID: cardID)
            }
        }
    }

    /// "kapsa|<card>|<place>" -> card id.
    static func cardID(from identifier: String) -> UUID? {
        let parts = identifier.split(separator: "|")
        guard parts.count == 3, parts[0] == "kapsa" else { return nil }
        return UUID(uuidString: String(parts[1]))
    }
}

// MARK: - Logos.swift

/// Shop logos: the website's icon (via Google's icon service), kept on the phone so
/// cards keep their logo offline. Unknown sites answer with a tiny globe, which is
/// treated as "no logo" (the card then shows its category icon).
@MainActor
@Observable
final class LogoStore {
    static let shared = LogoStore()

    private(set) var images: [String: UIImage] = [:]
    @ObservationIgnored private var tried: Set<String> = []

    private var folder: URL {
        let dir = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0].appendingPathComponent("logos")
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    func load(_ domain: String) async {
        guard !domain.isEmpty, images[domain] == nil, !tried.contains(domain) else { return }
        tried.insert(domain)
        let file = folder.appendingPathComponent(domain + ".png")
        if let data = try? Data(contentsOf: file), let image = UIImage(data: data) {
            images[domain] = image
            return
        }
        guard let url = URL(string: "https://www.google.com/s2/favicons?domain=\(domain)&sz=128") else { return }
        guard let result = try? await URLSession.shared.data(from: url) else { return }
        let (data, response) = result
        guard (response as? HTTPURLResponse)?.statusCode == 200,
              let image = UIImage(data: data),
              image.size.width * image.scale >= 32
        else { return }
        images[domain] = image
        try? data.write(to: file, options: .atomic)
    }

    /// A picked picture as a small square logo (128 px), centred and cropped.
    static func squareLogo(from image: UIImage) -> Data? {
        let side = min(image.size.width, image.size.height)
        guard side > 0 else { return nil }
        let target = CGSize(width: 128, height: 128)
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        let scaled = UIGraphicsImageRenderer(size: target, format: format).image { _ in
            let scale = 128 / side
            let w = image.size.width * scale
            let h = image.size.height * scale
            image.draw(in: CGRect(x: (128 - w) / 2, y: (128 - h) / 2, width: w, height: h))
        }
        if let png = scaled.pngData(), png.count <= 60_000 {
            return png
        }
        return scaled.jpegData(compressionQuality: 0.85)
    }
}

// MARK: - Scanner.swift

/// A code read by the camera or from a photo.
struct ScannedCode: Equatable, Sendable {
    let value: String
    let format: BarcodeFormat
}

enum CodeReader {
    /// Our format for what Vision found (UPC-A arrives as EAN-13 with a leading 0).
    static func format(for symbology: VNBarcodeSymbology) -> BarcodeFormat {
        switch symbology {
        case .ean13: .ean13
        case .ean8: .ean8
        case .code39, .code39Checksum, .code39FullASCII, .code39FullASCIIChecksum: .code39
        case .qr: .qr
        case .pdf417: .pdf417
        case .aztec: .aztec
        default: .code128
        }
    }

    /// Find a code in a photo (screenshot of an app card, photo of a plastic card).
    static func read(from image: UIImage) -> ScannedCode? {
        guard let cg = image.cgImage else { return nil }
        let request = VNDetectBarcodesRequest()
        let handler = VNImageRequestHandler(cgImage: cg, options: [:])
        do {
            try handler.perform([request])
        } catch {
            return nil
        }
        guard let best = request.results?.first(where: { $0.payloadStringValue?.isEmpty == false }),
              let value = best.payloadStringValue
        else { return nil }
        return ScannedCode(value: value, format: format(for: best.symbology))
    }

    /// The live scanner needs a recent iPhone (A12 chip or newer) and camera access.
    static var liveScannerWorks: Bool {
        DataScannerViewController.isSupported && DataScannerViewController.isAvailable
    }
}

/// Apple's live barcode scanner, wrapped for SwiftUI. Calls `onCode` once.
struct LiveScanner: UIViewControllerRepresentable {
    let onCode: (ScannedCode) -> Void

    func makeUIViewController(context: Context) -> DataScannerViewController {
        let scanner = DataScannerViewController(
            recognizedDataTypes: [.barcode()],
            qualityLevel: .balanced,
            recognizesMultipleItems: false,
            isHighFrameRateTrackingEnabled: false,
            isPinchToZoomEnabled: true,
            isGuidanceEnabled: true,
            isHighlightingEnabled: true
        )
        scanner.delegate = context.coordinator
        return scanner
    }

    func updateUIViewController(_ scanner: DataScannerViewController, context: Context) {
        if !scanner.isScanning {
            try? scanner.startScanning()
        }
    }

    static func dismantleUIViewController(_ scanner: DataScannerViewController, coordinator: Coordinator) {
        scanner.stopScanning()
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(onCode: onCode)
    }

    final class Coordinator: NSObject, DataScannerViewControllerDelegate {
        let onCode: (ScannedCode) -> Void
        private var done = false

        init(onCode: @escaping (ScannedCode) -> Void) {
            self.onCode = onCode
        }

        func dataScanner(_ dataScanner: DataScannerViewController, didAdd addedItems: [RecognizedItem], allItems: [RecognizedItem]) {
            guard !done else { return }
            for item in addedItems {
                if case let .barcode(barcode) = item, let value = barcode.payloadStringValue, !value.isEmpty {
                    done = true
                    UINotificationFeedbackGenerator().notificationOccurred(.success)
                    dataScanner.stopScanning()
                    onCode(ScannedCode(value: value, format: CodeReader.format(for: barcode.observation.symbology)))
                    return
                }
            }
        }
    }
}

