// MARK: - Places

struct PlacesSection: View {
    let card: Card
    @Environment(Store.self) private var store
    @State private var searching = false

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            SectionTitle(title: L("Místa", "Places"), count: card.places.count)
            if !card.places.isEmpty {
                Map(initialPosition: .automatic) {
                    ForEach(card.places) { place in
                        Marker(place.label.isEmpty ? card.name : place.label,
                               coordinate: CLLocationCoordinate2D(latitude: place.latitude, longitude: place.longitude))
                            .tint(card.look.dot)
                    }
                    UserAnnotation()
                }
                .frame(height: 190)
                .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
                .allowsHitTesting(false)
            }
            Panel {
                if card.places.isEmpty {
                    Text(L("Ulož místo obchodu a karta tam sama vyskočí.", "Save the shop's place and the card pops up there by itself."))
                        .font(.subheadline)
                        .foregroundStyle(Theme.ink2)
                }
                ForEach(card.places) { place in
                    HStack(spacing: 10) {
                        Image(systemName: "mappin.circle.fill").foregroundStyle(card.look.dot)
                        VStack(alignment: .leading, spacing: 1) {
                            Text(place.label.isEmpty ? L("Uložené místo", "Saved place") : place.label)
                                .font(.subheadline.weight(.semibold))
                                .foregroundStyle(Theme.ink)
                                .lineLimit(1)
                            if let here = store.location {
                                let d = CLLocation(latitude: place.latitude, longitude: place.longitude).distance(from: here)
                                Text(distanceText(d)).font(.caption).foregroundStyle(Theme.ink2)
                            }
                        }
                        Spacer()
                        Button {
                            store.removePlace(card.id, place.id)
                        } label: {
                            Image(systemName: "xmark.circle.fill").foregroundStyle(Theme.ink3)
                        }
                        .buttonStyle(.plain)
                    }
                }
                HStack(spacing: 10) {
                    Button {
                        if let here = store.location {
                            store.addPlace(card.id, Place(latitude: here.coordinate.latitude, longitude: here.coordinate.longitude))
                            store.show(L("Místo uloženo", "Place saved"))
                        } else {
                            LocationService.shared.requestWhenInUse()
                            store.show(L("Hledám polohu…", "Finding your location…"))
                        }
                    } label: {
                        Label(L("Tady", "Here"), systemImage: "location.fill")
                    }
                    .buttonStyle(PrimaryButtonStyle())
                    Button {
                        searching = true
                    } label: {
                        Label(L("Adresa", "Address"), systemImage: "magnifyingglass")
                    }
                    .buttonStyle(SecondaryButtonStyle())
                }
            }
        }
        .sheet(isPresented: $searching) {
            AddressSearchSheet(card: card)
        }
    }
}

// MARK: - Sheets.swift

/// Shows whichever sheet the store asks for.
struct SheetHost: View {
    let sheet: AppSheet
    @Environment(Store.self) private var store

    var body: some View {
        switch sheet {
        case let .addCard(kind):
            AddCardFlow(kind: kind)
        case let .editCard(id):
            if let card = store.card(id) {
                NavigationStack {
                    CardFormView(original: card, isNew: false)
                }
            }
        case let .addCoupon(cardID):
            NavigationStack {
                CouponFormView(original: Coupon(title: "", cardID: cardID), isNew: true)
            }
        case let .editCoupon(id):
            if let coupon = store.coupon(id) {
                NavigationStack {
                    CouponFormView(original: coupon, isNew: false)
                }
            }
        case let .promo(id):
            PromoSheet(cardID: id)
        case let .pay(id):
            PaySheet(cardID: id)
        case let .logSpend(id):
            LogSpendSheet(cardID: id)
        }
    }
}

// MARK: - Pay with a gift card

struct PaySheet: View {
    let cardID: UUID
    @Environment(Store.self) private var store
    @Environment(\.dismiss) private var dismiss
    @State private var amount = ""
    @State private var settingBalance = false
    @State private var error = ""
    @FocusState private var focused: Bool

    var body: some View {
        NavigationStack {
            if let card = store.card(cardID) {
                let balance = card.balance ?? 0
                ScrollView {
                    VStack(spacing: 16) {
                        WalletCardView(card: card, distance: nil, coupons: 0, isHere: false)
                        Text(settingBalance ? L("Zůstatek na kartě", "Balance on the card") : L("Kolik platíš", "Amount to pay"))
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(Theme.ink2)
                        TextField("0", text: $amount)
                            .keyboardType(.decimalPad)
                            .font(.system(size: 44, weight: .bold))
                            .multilineTextAlignment(.center)
                            .focused($focused)
                            .padding(.vertical, 8)
                            .background(Theme.surface, in: RoundedRectangle(cornerRadius: 16, style: .continuous))
                            .overlay(RoundedRectangle(cornerRadius: 16, style: .continuous).stroke(Theme.line))
                            .foregroundStyle(Theme.ink)
                        if !settingBalance, balance > 0 {
                            Button(L("Celý zůstatek · \(money(balance, store.settings.currency))", "All of it · \(money(balance, store.settings.currency))")) {
                                amount = plain(balance)
                            }
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(Theme.accent)
                        }
                        if !error.isEmpty {
                            Text(error).font(.subheadline.weight(.semibold)).foregroundStyle(.red)
                        }
                        Button {
                            submit(card)
                        } label: {
                            Label(settingBalance ? L("Uložit zůstatek", "Save balance") : L("Zaplatit", "Pay"),
                                  systemImage: settingBalance ? "checkmark" : "wallet.pass")
                        }
                        .buttonStyle(PrimaryButtonStyle())
                        Button(settingBalance ? L("Zpět k placení", "Back to paying") : L("Je zůstatek jinak? Upravit", "Balance is different? Fix it")) {
                            settingBalance.toggle()
                            amount = settingBalance ? plain(balance) : ""
                            error = ""
                        }
                        .font(.subheadline)
                        .foregroundStyle(Theme.ink2)
                    }
                    .padding(18)
                }
                .background(Theme.bg.ignoresSafeArea())
                .navigationTitle(settingBalance ? L("Zůstatek", "Balance") : L("Zaplatit dárkovou kartou", "Pay with gift card"))
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button(L("Zrušit", "Cancel")) { dismiss() }
                    }
                }
                .onAppear { focused = true }
            }
        }
        .presentationDetents([.large])
    }

    private func plain(_ value: Double) -> String {
        value.formatted(.number.precision(.fractionLength(0...2)).grouping(.never))
    }

    private func submit(_ card: Card) {
        guard let value = parseMoney(amount), value >= 0, settingBalance || value > 0 else {
            error = L("Napiš částku.", "Type an amount.")
            return
        }
        let currency = store.settings.currency
        if settingBalance {
            store.setBalance(card.id, value)
            store.show(L("Zůstatek uložen", "Balance saved"))
            dismiss()
            return
        }
        let balance = card.balance ?? 0
        guard value <= balance + 0.001 else {
            error = L("Na kartě je jen \(money(balance, currency)).", "Only \(money(balance, currency)) left on the card.")
            return
        }
        if let purchase = store.pay(card.id, amount: value) {
            let left = store.card(card.id)?.balance ?? 0
            let shared = store
            store.show(
                L("Zaplaceno \(money(value, currency)) · zbývá \(money(left, currency))", "Paid \(money(value, currency)) · \(money(left, currency)) left"),
                actionTitle: L("Vrátit", "Undo")
            ) {
                shared.undoPayment(purchase.id)
            }
        }
        dismiss()
    }
}

// MARK: - Promo code for a card

struct PromoSheet: View {
    let cardID: UUID
    @Environment(Store.self) private var store
    @Environment(\.dismiss) private var dismiss
    @State private var code = ""
    @State private var discount = ""
    @State private var hasExpiry = false
    @State private var expiry = Date().addingTimeInterval(14 * 86_400)

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField(L("Kód, např. LETO20", "Code, e.g. SUMMER20"), text: $code)
                        .font(.system(.title3, design: .monospaced))
                        .textInputAutocapitalization(.characters)
                        .autocorrectionDisabled()
                } header: {
                    Text(L("Promo kód", "Promo code"))
                }
                Section {
                    TextField(L("Co dává, např. −20 %", "What it gives, e.g. −20%"), text: $discount)
                    Toggle(L("Platí do", "Valid until"), isOn: $hasExpiry)
                    if hasExpiry {
                        DatePicker(L("Datum", "Date"), selection: $expiry, displayedComponents: .date)
                    }
                } footer: {
                    Text(L("Kód uvidíš pod kartou, když přijdeš do obchodu, i s tlačítkem Kopírovat.",
                           "You'll see the code under the card when you walk into the shop, with a Copy button."))
                }
            }
            .scrollContentBackground(.hidden)
            .background(Theme.bg.ignoresSafeArea())
            .navigationTitle(store.card(cardID)?.name ?? L("Promo kód", "Promo code"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(L("Zrušit", "Cancel")) { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(L("Uložit", "Save")) { save() }
                        .disabled(code.trimmingCharacters(in: .whitespaces).isEmpty)
                }
            }
        }
        .presentationDetents([.medium, .large])
    }

    private func save() {
        let clean = code.trimmingCharacters(in: .whitespaces)
        let coupon = Coupon(
            title: L("Promo kód", "Promo code"),
            discount: String(discount.trimmingCharacters(in: .whitespaces).prefix(24)),
            cardID: cardID,
            shop: store.card(cardID)?.name ?? "",
            code: clean,
            format: Barcodes.guess(clean),
            expiry: hasExpiry ? expiry : nil
        )
        store.saveCoupon(coupon)
        store.confetti += 1
        store.show(L("Promo kód uložen", "Promo code saved"))
        dismiss()
    }
}

// MARK: - Log spending

struct LogSpendSheet: View {
    @Environment(Store.self) private var store
    @Environment(\.dismiss) private var dismiss
    @State private var cardID: UUID?
    @State private var amount = ""
    @State private var shop = ""
    @State private var saved = ""
    @State private var date = Date()
    @State private var fromGift = true
    @State private var error = ""

    init(cardID: UUID?) {
        _cardID = State(initialValue: cardID)
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField("0", text: $amount)
                        .keyboardType(.decimalPad)
                        .font(.system(size: 34, weight: .bold))
                } header: {
                    Text(L("Kolik jsi utratil(a) (\(store.settings.currency))", "How much you spent (\(store.settings.currency))"))
                }
                Section {
                    Picker(L("Obchod", "Shop"), selection: $cardID) {
                        Text(L("Jiný obchod", "Other shop")).tag(UUID?.none)
                        ForEach(store.cards) { card in
                            Text(card.name).tag(UUID?.some(card.id))
                        }
                    }
                    if cardID == nil {
                        TextField(L("Název obchodu", "Shop name"), text: $shop)
                    }
                    if let id = cardID, let card = store.card(id), card.isGift, Calendar.current.isDateInToday(date) {
                        Toggle(L("Zaplaceno dárkovou kartou (zbývá \(money(card.balance ?? 0, store.settings.currency)))",
                                 "Paid with the gift card (\(money(card.balance ?? 0, store.settings.currency)) left)"), isOn: $fromGift)
                    }
                    DatePicker(L("Kdy", "When"), selection: $date, in: ...Date(), displayedComponents: .date)
                }
                Section {
                    TextField("0", text: $saved).keyboardType(.decimalPad)
                } header: {
                    Text(L("Ušetřeno (nepovinné)", "Saved (optional)"))
                }
                if !error.isEmpty {
                    Text(error).foregroundStyle(.red)
                }
            }
            .scrollContentBackground(.hidden)
            .background(Theme.bg.ignoresSafeArea())
            .navigationTitle(L("Zapsat útratu", "Log spending"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(L("Zrušit", "Cancel")) { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(L("Uložit", "Save")) { save() }
                }
            }
        }
    }

    private func save() {
        guard let value = parseMoney(amount), value > 0 else {
            error = L("Napiš částku.", "Type an amount.")
            return
        }
        let card = cardID.flatMap { store.card($0) }
        if let card, card.isGift, fromGift, Calendar.current.isDateInToday(date) {
            guard value <= (card.balance ?? 0) + 0.001 else {
                error = L("Na kartě je jen \(money(card.balance ?? 0, store.settings.currency)).", "Only \(money(card.balance ?? 0, store.settings.currency)) left on the card.")
                return
            }
            store.pay(card.id, amount: value)
        } else {
            let name = card?.name ?? shop.trimmingCharacters(in: .whitespaces)
            store.logPurchase(Purchase(cardID: card?.id, shop: name, amount: value, saved: parseMoney(saved) ?? 0, date: date))
        }
        store.show(L("Zapsáno", "Saved"))
        dismiss()
    }
}

// MARK: - Find a shop's address

struct AddressSearchSheet: View {
    let card: Card
    @Environment(Store.self) private var store
    @Environment(\.dismiss) private var dismiss
    @State private var query = ""
    @State private var hits: [Hit] = []
    @State private var busy = false
    @State private var nothing = false

    struct Hit: Identifiable {
        let id = UUID()
        let name: String
        let detail: String
        let latitude: Double
        let longitude: Double
    }

    var body: some View {
        NavigationStack {
            List {
                Section {
                    HStack {
                        TextField(L("Obchod nebo adresa", "Shop or address"), text: $query)
                            .submitLabel(.search)
                            .onSubmit { Task { await search() } }
                        if busy {
                            ProgressView()
                        } else {
                            Button {
                                Task { await search() }
                            } label: {
                                Image(systemName: "magnifyingglass")
                            }
                        }
                    }
                }
                if nothing {
                    Text(L("Nic jsem nenašel.", "Nothing found.")).foregroundStyle(.secondary)
                }
                ForEach(hits) { hit in
                    Button {
                        store.addPlace(card.id, Place(latitude: hit.latitude, longitude: hit.longitude, label: [hit.name, hit.detail].filter { !$0.isEmpty }.joined(separator: ", ")))
                        store.show(L("Místo uloženo", "Place saved"))
                        dismiss()
                    } label: {
                        VStack(alignment: .leading, spacing: 2) {
                            Text(hit.name).font(.headline).foregroundStyle(Theme.ink)
                            if !hit.detail.isEmpty {
                                Text(hit.detail).font(.footnote).foregroundStyle(Theme.ink2)
                            }
                            if let here = store.location {
                                let d = CLLocation(latitude: hit.latitude, longitude: hit.longitude).distance(from: here)
                                Text(distanceText(d)).font(.caption).foregroundStyle(Theme.ink3)
                            }
                        }
                    }
                }
            }
            .navigationTitle(L("Najít místo", "Find a place"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(L("Zrušit", "Cancel")) { dismiss() }
                }
            }
            .onAppear {
                if query.isEmpty {
                    query = card.name
                }
            }
        }
    }

    private func search() async {
        let text = query.trimmingCharacters(in: .whitespaces)
        guard !text.isEmpty else { return }
        busy = true
        nothing = false
        defer { busy = false }
        let request = MKLocalSearch.Request()
        request.naturalLanguageQuery = text
        if let here = store.location {
            request.region = MKCoordinateRegion(center: here.coordinate, latitudinalMeters: 30_000, longitudinalMeters: 30_000)
        }
        do {
            let response = try await MKLocalSearch(request: request).start()
            hits = response.mapItems.prefix(15).map { item in
                Hit(
                    name: item.name ?? text,
                    detail: item.placemark.title ?? "",
                    latitude: item.placemark.coordinate.latitude,
                    longitude: item.placemark.coordinate.longitude
                )
            }
            nothing = hits.isEmpty
        } catch {
            hits = []
            nothing = true
        }
    }
}

// MARK: - CardForm.swift

/// New card or gift card: camera first, then the form.
struct AddCardFlow: View {
    let kind: CardKind
    @State private var draft: Card?

    var body: some View {
        NavigationStack {
            if let draft {
                CardFormView(original: draft, isNew: true)
            } else {
                ScanStep(kind: kind) { scanned in
                    draft = Card(name: "", code: scanned.value, format: scanned.format, kind: kind)
                } onManual: {
                    draft = Card(name: "", format: .none, kind: kind)
                }
            }
        }
    }
}

/// Live camera scanner with "from a photo" and "type it in" below.
struct ScanStep: View {
    let kind: CardKind
    let onCode: (ScannedCode) -> Void
    let onManual: () -> Void
    @Environment(\.dismiss) private var dismiss
    @State private var photo: PhotosPickerItem?
    @State private var message = ""

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()
            if CodeReader.liveScannerWorks {
                LiveScanner(onCode: onCode).ignoresSafeArea()
            } else {
                VStack(spacing: 12) {
                    Image(systemName: "camera.fill").font(.system(size: 40))
                    Text(L("Živé skenování tu nejde (chybí kamera nebo povolení). Vyfoť kartu, nebo napiš číslo.",
                           "Live scanning isn't available here (no camera or no permission). Use a photo or type the number."))
                        .multilineTextAlignment(.center)
                }
                .foregroundStyle(.white)
                .padding(30)
            }
            VStack {
                Text(L("Namiř na čárový kód karty", "Point at the card's barcode"))
                    .font(.subheadline.weight(.semibold))
                    .foregroundStyle(.white)
                    .padding(.horizontal, 14)
                    .padding(.vertical, 8)
                    .background(Color.black.opacity(0.5), in: Capsule())
                    .padding(.top, 12)
                Spacer()
                if !message.isEmpty {
                    Text(message)
                        .font(.subheadline.weight(.semibold))
                        .foregroundStyle(.white)
                        .padding(12)
                        .background(Color.black.opacity(0.6), in: RoundedRectangle(cornerRadius: 12))
                }
                HStack(spacing: 10) {
                    PhotosPicker(selection: $photo, matching: .images) {
                        Label(L("Z fotky", "From photo"), systemImage: "photo")
                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(GlassButtonStyle(strong: true))
                    Button {
                        onManual()
                    } label: {
                        Label(L("Napsat ručně", "Type it in"), systemImage: "keyboard")
                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(GlassButtonStyle(strong: true))
                }
                .padding(.horizontal, 18)
                .padding(.bottom, 24)
            }
        }
        .navigationTitle(kind == .gift ? L("Dárková karta", "Gift card") : L("Nová karta", "New card"))
        .navigationBarTitleDisplayMode(.inline)
        .toolbarBackground(.visible, for: .navigationBar)
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button(L("Zrušit", "Cancel")) { dismiss() }
            }
        }
        .onChange(of: photo) {
            Task { await readPhoto() }
        }
    }

    private func readPhoto() async {
        guard let photo,
              let data = try? await photo.loadTransferable(type: Data.self),
              let image = UIImage(data: data)
        else { return }
        if let code = CodeReader.read(from: image) {
            onCode(code)
        } else {
            message = L("Na fotce jsem kód nenašel. Zkus jinou, nebo napiš číslo.", "No code found in the photo. Try another one or type the number.")
        }
    }
}

/// The card form, for new cards and for editing.
struct CardFormView: View {
    let isNew: Bool
    @Environment(Store.self) private var store
    @Environment(\.dismiss) private var dismiss
    @State private var card: Card
    @State private var initialText: String
    @State private var balanceText: String
    @State private var pointsText: String
    @State private var pointsGoalText: String
    @State private var hasExpiry: Bool
    @State private var expiry: Date
    @State private var stampsOn: Bool
    @State private var stampGoal: Int
    @State private var reward: String
    @State private var saveHere = true
    @State private var colorTouched: Bool
    @State private var logoItem: PhotosPickerItem?
    @State private var rescanning = false

    init(original: Card, isNew: Bool) {
        self.isNew = isNew
        _card = State(initialValue: original)
        let plain: (Double?) -> String = { value in
            value.map { $0.formatted(.number.precision(.fractionLength(0...2)).grouping(.never)) } ?? ""
        }
        _initialText = State(initialValue: plain(original.initialBalance))
        _balanceText = State(initialValue: plain(original.balance))
        _pointsText = State(initialValue: original.points.map(String.init) ?? "")
        _pointsGoalText = State(initialValue: original.pointsGoal.map(String.init) ?? "")
        _hasExpiry = State(initialValue: original.expiry != nil)
        _expiry = State(initialValue: original.expiry ?? Date().addingTimeInterval(365 * 86_400))
        _stampsOn = State(initialValue: original.stamps != nil)
        _stampGoal = State(initialValue: original.stamps?.goal ?? 10)
        _reward = State(initialValue: original.stamps?.reward ?? "")
        _colorTouched = State(initialValue: !isNew)
    }

    var body: some View {
        Form {
            Section {
                Picker(L("Druh karty", "Card type"), selection: $card.kind) {
                    Text(L("Věrnostní karta", "Loyalty card")).tag(CardKind.loyalty)
                    Text(L("Dárková karta", "Gift card")).tag(CardKind.gift)
                }
                .pickerStyle(.segmented)
                WalletCardView(card: preview, distance: nil, coupons: 0, isHere: false)
                    .listRowInsets(EdgeInsets(top: 8, leading: 0, bottom: 8, trailing: 0))
            }
            .listRowBackground(Color.clear)

            Section {
                TextField(L("Název obchodu", "Shop name"), text: $card.name)
                    .textInputAutocapitalization(.words)
                    .onChange(of: card.name) {
                        if let brand = Brands.find(card.name) {
                            apply(brand)
                        }
                    }
                let suggestions = Brands.suggest(card.name, limit: 5)
                if !suggestions.isEmpty {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 8) {
                            ForEach(suggestions, id: \.name) { brand in
                                Button {
                                    card.name = brand.name
                                    apply(brand)
                                } label: {
                                    HStack(spacing: 6) {
                                        Circle()
                                            .fill(Looks.look(colorHex: brand.color, category: brand.category, kind: .loyalty).dot)
                                            .frame(width: 10, height: 10)
                                        Text(brand.name)
                                    }
                                    .font(.subheadline.weight(.semibold))
                                    .padding(.horizontal, 12)
                                    .frame(height: 34)
                                    .background(Theme.surface2, in: Capsule())
                                }
                                .buttonStyle(.plain)
                            }
                        }
                    }
                }
            } header: {
                Text(L("Obchod", "Shop"))
            }

            Section {
                TextField(L("Číslo pod čárovým kódem", "Number under the barcode"), text: $card.code)
                    .font(.system(.body, design: .monospaced))
                    .textInputAutocapitalization(.characters)
                    .autocorrectionDisabled()
                    .onChange(of: card.code) {
                        if card.format == .none || isNew {
                            card.format = Barcodes.guess(card.code)
                        }
                    }
                Picker(L("Typ kódu", "Code type"), selection: $card.format) {
                    ForEach(BarcodeFormat.allCases) { format in
                        Text(format.label).tag(format)
                    }
                }
                Button {
                    rescanning = true
                } label: {
                    Label(L("Naskenovat kód", "Scan the code"), systemImage: "barcode.viewfinder")
                }
            } header: {
                Text(card.isGift ? L("Číslo dárkové karty", "Gift card number") : L("Číslo karty", "Card number"))
            }

            if card.isGift {
                Section {
                    TextField(L("Hodnota karty, např. 1000", "Card value, e.g. 1000"), text: $initialText)
                        .keyboardType(.decimalPad)
                    TextField(L("Zbývá teď (když už jsi platil/a)", "Left now (if already used)"), text: $balanceText)
                        .keyboardType(.decimalPad)
                    TextField("PIN", text: $card.pin)
                        .font(.system(.body, design: .monospaced))
                        .autocorrectionDisabled()
                } header: {
                    Text(L("Peníze na kartě (\(store.settings.currency))", "Money on the card (\(store.settings.currency))"))
                }
            }

            Section {
                Toggle(L("Má datum platnosti", "Has an expiry date"), isOn: $hasExpiry)
                if hasExpiry {
                    DatePicker(L("Platí do", "Valid until"), selection: $expiry, displayedComponents: .date)
                }
            } footer: {
                Text(card.isGift
                    ? L("Kapsa ti připomene dva týdny předem, ať peníze nepropadnou.", "Kapsa reminds you two weeks before, so the money isn't lost.")
                    : L("Kapsa ti připomene, než karta skončí.", "Kapsa reminds you before the card expires."))
            }

            Section {
                LazyVGrid(columns: [GridItem(.adaptive(minimum: 40), spacing: 12)], spacing: 12) {
                    ForEach(Brands.swatches, id: \.self) { hex in
                        Circle()
                            .fill(Looks.look(colorHex: hex, category: card.category, kind: card.kind).gradient)
                            .frame(width: 40, height: 40)
                            .overlay(Circle().stroke(card.colorHex == hex ? Theme.accent : Color.clear, lineWidth: 3).padding(-4))
                            .onTapGesture {
                                card.colorHex = hex
                                colorTouched = true
                            }
                    }
                }
                .padding(.vertical, 6)
                ColorPicker(L("Vlastní barva", "Own colour"), selection: colorBinding, supportsOpacity: false)
            } header: {
                Text(L("Barva", "Colour"))
            }

            Section {
                HStack(spacing: 12) {
                    LogoView(card: card, size: 44)
                        .background(card.look.gradient, in: Circle())
                    TextField(Brands.find(card.name)?.domain ?? L("web obchodu, např. obchod.cz", "shop website, e.g. shop.com"), text: $card.website)
                        .keyboardType(.URL)
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                }
                PhotosPicker(selection: $logoItem, matching: .images) {
                    Label(L("Vlastní obrázek loga", "Own logo picture"), systemImage: "photo")
                }
                if card.logoData != nil {
                    Button(L("Odebrat obrázek", "Remove picture"), role: .destructive) {
                        card.logoData = nil
                    }
                }
            } header: {
                Text("Logo")
            } footer: {
                Text(L("Logo se vezme z webu obchodu. Nebo vyber vlastní obrázek.", "The logo comes from the shop's website, or pick your own picture."))
            }

            Section {
                Picker(L("Kategorie", "Category"), selection: $card.category) {
                    ForEach(ShopCategory.allCases) { category in
                        Label(category.name, systemImage: category.symbol).tag(category)
                    }
                }
                if !card.isGift {
                    Toggle(L("Sbírám razítka", "Collect stamps"), isOn: $stampsOn)
                    if stampsOn {
                        Stepper(L("Razítek na odměnu: \(stampGoal)", "Stamps for a reward: \(stampGoal)"), value: $stampGoal, in: 2...30)
                        TextField(L("Odměna, např. Káva zdarma", "Reward, e.g. Free coffee"), text: $reward)
                    }
                    TextField(L("Body", "Points"), text: $pointsText).keyboardType(.numberPad)
                    TextField(L("Cíl bodů (nepovinné)", "Points goal (optional)"), text: $pointsGoalText).keyboardType(.numberPad)
                }
                TextField(L("Poznámka", "Note"), text: $card.note, axis: .vertical)
                    .lineLimit(1...4)
            } header: {
                Text(L("Další", "More"))
            }

            if isNew, store.location != nil {
                Section {
                    Toggle(L("Uložit místo, kde právě jsem", "Save the place where I am"), isOn: $saveHere)
                } footer: {
                    Text(L("Až sem příště přijdeš, karta vyskočí sama.", "Next time you're here, the card pops up by itself."))
                }
            }
        }
        .scrollContentBackground(.hidden)
        .background(Theme.bg.ignoresSafeArea())
        .navigationTitle(isNew ? (card.isGift ? L("Nová dárková karta", "New gift card") : L("Nová karta", "New card")) : L("Upravit kartu", "Edit card"))
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .cancellationAction) {
                Button(L("Zrušit", "Cancel")) { dismiss() }
            }
            ToolbarItem(placement: .confirmationAction) {
                Button(L("Uložit", "Save")) { save() }
                    .fontWeight(.bold)
                    .disabled(card.name.trimmingCharacters(in: .whitespaces).isEmpty)
            }
        }
        .sheet(isPresented: $rescanning) {
            NavigationStack {
                ScanStep(kind: card.kind) { scanned in
                    card.code = scanned.value
                    card.format = scanned.format
                    rescanning = false
                } onManual: {
                    rescanning = false
                }
            }
        }
        .onChange(of: logoItem) {
            Task {
                guard let item = logoItem,
                      let data = try? await item.loadTransferable(type: Data.self),
                      let image = UIImage(data: data)
                else { return }
                card.logoData = LogoStore.squareLogo(from: image)
            }
        }
    }

    /// What the card will look like (gift balance from the typed text).
    private var preview: Card {
        var c = card
        if c.name.isEmpty {
            c.name = L("Název obchodu", "Shop name")
        }
        if c.isGift {
            c.balance = parseMoney(balanceText) ?? parseMoney(initialText) ?? 0
        }
        return c
    }

    private var colorBinding: Binding<Color> {
        Binding(
            get: { RGB(hex: card.colorHex)?.color ?? Theme.accent },
            set: { newColor in
                var r: CGFloat = 0
                var g: CGFloat = 0
                var b: CGFloat = 0
                var a: CGFloat = 0
                _ = UIColor(newColor).getRed(&r, green: &g, blue: &b, alpha: &a)
                card.colorHex = RGB(r: Double(r), g: Double(g), b: Double(b)).hex
                colorTouched = true
            }
        )
    }

    private func apply(_ brand: Brand) {
        if !colorTouched {
            card.colorHex = brand.color
        }
        card.category = brand.category
    }

    private func save() {
        var c = card
        c.name = c.name.trimmingCharacters(in: .whitespaces)
        c.code = c.code.trimmingCharacters(in: .whitespaces)
        if c.code.isEmpty {
            c.format = .none
        } else if c.format == .none {
            c.format = Barcodes.guess(c.code)
        }
        c.website = cleanDomain(c.website)
        c.expiry = hasExpiry ? expiry : nil
        if c.isGift {
            c.initialBalance = parseMoney(initialText)
            c.balance = parseMoney(balanceText) ?? c.initialBalance ?? 0
            c.stamps = nil
            c.points = nil
            c.pointsGoal = nil
        } else {
            c.balance = nil
            c.initialBalance = nil
            c.pin = ""
            if stampsOn {
                let old = store.card(c.id)?.stamps
                c.stamps = Stamps(goal: stampGoal, count: min(old?.count ?? 0, stampGoal), reward: reward, redeemed: old?.redeemed ?? 0)
            } else {
                c.stamps = nil
            }
            c.points = Int(pointsText.filter(\.isNumber))
            c.pointsGoal = Int(pointsGoalText.filter(\.isNumber))
        }
        if isNew, saveHere, let here = store.location {
            c.places.append(Place(latitude: here.coordinate.latitude, longitude: here.coordinate.longitude))
        }
        store.upsert(c)
        if isNew {
            store.confetti += 1
            store.show(L("Karta uložena", "Card saved"))
            store.open(cardID: c.id)
        } else {
            store.show(L("Uloženo", "Saved"))
            dismiss()
        }
    }
}

// MARK: - CouponsView.swift

/// Coupons tab: active, ending soon and used coupons and promo codes.
struct CouponsView: View {
    @Environment(Store.self) private var store
    @State private var filter: Filter = .active

    enum Filter: Hashable {
        case active, soon, used
    }

    var body: some View {
        @Bindable var store = store
        NavigationStack(path: $store.couponsPath) {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    Button {
                        store.sheet = .addCoupon(nil)
                    } label: {
                        Label(L("Přidat kupón nebo promo kód", "Add a coupon or promo code"), systemImage: "plus")
                    }
                    .buttonStyle(PrimaryButtonStyle())
                    ChipPicker(options: [
                        (.active, L("Aktivní · \(active.count)", "Active · \(active.count)")),
                        (.soon, L("Brzy končí · \(soon.count)", "Ending soon · \(soon.count)")),
                        (.used, L("Použité · \(used.count)", "Used · \(used.count)")),
                    ], selection: $filter)
                    let list = filter == .active ? active : filter == .soon ? soon : used
                    if list.isEmpty {
                        Text(filter == .used ? L("Zatím nic použitého.", "Nothing used yet.") : L("Žádné kupóny. Přidej první!", "No coupons. Add your first!"))
                            .foregroundStyle(Theme.ink2)
                            .frame(maxWidth: .infinity, minHeight: 100)
                    }
                    ForEach(list) { coupon in
                        NavigationLink(value: CouponRoute(id: coupon.id)) {
                            CouponRow(coupon: coupon)
                        }
                        .buttonStyle(LiftButtonStyle())
                    }
                }
                .padding(.horizontal, 18)
                .padding(.bottom, 40)
            }
            .background(Theme.bg.ignoresSafeArea())
            .navigationTitle(L("Kupóny", "Coupons"))
            .navigationDestination(for: CouponRoute.self) { route in
                CouponDetailView(couponID: route.id)
            }
            .navigationDestination(for: CardRoute.self) { route in
                CardDetailView(cardID: route.id)
            }
        }
    }

    private var active: [Coupon] {
        store.coupons.filter { store.isActive($0) }.sorted { ($0.expiry ?? .distantFuture) < ($1.expiry ?? .distantFuture) }
    }

    private var soon: [Coupon] {
        active.filter { ($0.expiry?.daysFromToday ?? 99) <= store.settings.remindDays }
    }

    private var used: [Coupon] {
        store.coupons.filter(\.used).sorted { ($0.usedAt ?? .distantPast) > ($1.usedAt ?? .distantPast) }
    }
}

/// "Ends in 3 days", "ends today", "expired", "used".
func couponStatus(_ c: Coupon, remindDays: Int) -> (text: String, warn: Bool) {
    if c.used {
        return (L("Použito", "Used"), false)
    }
    guard let e = c.expiry else {
        return (L("Bez data", "No end date"), false)
    }
    let days = e.daysFromToday
    if days < 0 {
        return (L("Prošlý", "Expired"), true)
    }
    if days == 0 {
        return (L("Končí dnes", "Ends today"), true)
    }
    return (L("Ještě \(days) d", "\(days) days left"), days <= remindDays)
}

